CREATE TABLE "distribution_experiments" ("id" text PRIMARY KEY NOT NULL,"org_id" text NOT NULL,"program_id" text NOT NULL REFERENCES "distribution_programs"("id"),"name" text NOT NULL,"hypothesis" text NOT NULL,"starts_at" timestamp with time zone,"ends_at" timestamp with time zone,"status" text DEFAULT 'PLANNED' NOT NULL,"comparison_dimensions" jsonb NOT NULL,"success_metric" text NOT NULL,"notes" text,"results" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "distribution_experiments_program_name_idx" ON "distribution_experiments" ("program_id","name"); CREATE INDEX "distribution_experiments_org_idx" ON "distribution_experiments" ("org_id");
CREATE TABLE "distribution_referral_sources" ("id" text PRIMARY KEY NOT NULL,"org_id" text NOT NULL,"user_id" text,"raw_answer" text NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE INDEX "distribution_referral_sources_org_idx" ON "distribution_referral_sources" ("org_id","created_at");
